node scripts/check.mjs; node scripts/summarize-automatic-pilot.mjs > /tmp/dip-pilot-summary-final.json; node --input-type=module - <<'NODE'
import fs from 'node:fs';const r=JSON.parse(fs.readFileSync('/tmp/dip-pilot-summary-final.json'));console.log(JSON.stringify({started:r.turnsStarted,finished:r.finishedAt,arms:r.arms,turns:r.turns.map(t=>({scenario:t.scenario,arm:t.arm,phase:t.phase,wallMs:t.wallMs,passed:t.functionalPassed,total:t.functionalTotal,memory:t.memoryPassed,callCount:t.calls.length,routine:t.calls.filter(c=>c.category==='routine-mutation').length,payload:t.measuredPayloadBytes}))}));
NODE
